SELECT ?investorId ?riskTolerance ?timeHorizon
WHERE {
  ?investor rdf:type wm:Investor .

  # Identify the investor by ID or name (case‑insensitive)
  {
    ?investor wm:investorId ?investorId .
    FILTER(LCASE(STR(?investorId)) = "INV-002")
  } UNION {
    ?investor wm:investorName ?name .
    FILTER(LCASE(STR(?name)) = "INV-002")
    BIND(?name AS ?investorId)
