SELECT ?investorId ?investorName ?holding_count
WHERE {
  # Pre‑aggregate holdings per investor for 2024
  {
    SELECT ?investor (COUNT(?holdingId) AS ?holding_count)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:purchaseDate ?purchaseDate ;
               wm:holdingId ?holdingId .
      BIND(xsd:date(?purchaseDate) AS ?pDate) .
      FILTER(?pDate >= "2024-01-01"^^xsd:date && ?pDate <= "2024-12-31"^^xsd:date)
    }
    GROUP BY ?investor
  }
  # Join to Investor to get identifiers and name
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName ?holding_count

