SELECT ?riskTolerance ?month (SUM(xsd:decimal(?amount)) AS ?total_cash_flow)
WHERE {
  ?cf a wm:CashFlow ;
      wm:date ?date ;
      wm:amount ?amount ;
      wm:cashFlowOfInvestor ?inv .
  FILTER(xsd:date(?date) >= "2025-01-01"^^xsd:date && xsd:date(?date) <= "2025-12-31"^^xsd:date)
  BIND(SUBSTR(STR(?date), 1, 7) AS ?month)
  OPTIONAL { ?inv wm:riskTolerance ?rt . }
  BIND(COALESCE(?rt, "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance ?month
ORDER BY ?riskTolerance ?month

