SELECT ?risk_tolerance_group
       (SUM(xsd:decimal(?holdingValue)) AS ?total_holding_value)
       (SUM(xsd:decimal(?sectorInvest)) AS ?total_sector_allocation_investment)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:riskTolerance ?rtRaw . }
  BIND(COALESCE(STR(?rtRaw), "NULL") AS ?risk_tolerance_group)

  {
    SELECT ?investorId (SUM(xsd:decimal(?cv)) AS ?holdingValue)
    WHERE {
      ?h a wm:PortfolioHolding ;
         wm:investorId ?investorId ;
         wm:currentValue ?cv .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?ti)) AS ?sectorInvest)
    WHERE {
      ?a a wm:SectorAllocation ;
         wm:investorId ?investorId ;
         wm:totalInvestment ?ti .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?risk_tolerance_group

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
