PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?total2025 WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?avgProgress) WHERE {
      ?investor a wm:Investor .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progress .
    }
    GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?progress)) < 40)
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?total2025) WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:date ?date .
      BIND (SUBSTR(STR(?date), 1, 4) AS ?year) .
      FILTER(?year = "2025")
    }
    GROUP BY ?investor
  }
  ?investor wm:investorName ?investorName .
}
ORDER BY DESC(?total2025)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
