PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?holdingCount ?cashflowCount
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  {
    SELECT ?investorId (COUNT(?holding) AS ?holdingCount)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?invHolder .
      ?invHolder wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?holding) > 0)
  }

  {
    SELECT ?investorId (COUNT(?cashflow) AS ?cashflowCount)
    WHERE {
      ?cashflow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?invCash ;
                wm:date ?cfDate .
      ?invCash wm:investorId ?investorId .
      FILTER ( xsd:date(?cfDate) >= "2025-01-01"^^xsd:date && xsd:date(?cfDate) <= "2025-12-31"^^xsd:date )
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cashflow) > 0)
  }
}

