PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_goal_shortfall ?total_holding_gain ?total_cash_flow WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_goal_shortfall) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:currentValue ?curr ;
               wm:cost ?cost ;
               wm:heldByInvestor ?invHolding .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
      ?invHolding wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_cash_flow) WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:cashFlowOfInvestor ?invCF .
      ?invCF wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  FILTER(?total_goal_shortfall > 0 && ?total_holding_gain < 0 && ?total_cash_flow < 10000)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?avgGoalProgress) AS ?avg_goal_progress)
       (AVG(?avgRiskScore) AS ?avg_risk_score)
       (SUM(?totalHoldingValue) AS ?total_holding_value)
WHERE {
  {
    SELECT ?inv ?riskTolerance (AVG(xsd:decimal(?progress)) AS ?avgGoalProgress) (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore) (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL {
        ?inv wm:riskTolerance ?rt .
        BIND(STR(?rt) AS ?rtStr)
      }
      BIND(COALESCE(?rtStr, "NULL") AS ?riskTolerance)

      OPTIONAL {
        ?goal a wm:InvestmentGoal ;
              wm:belongsToInvestor ?inv ;
              wm:progressPct ?progress .
      }
      OPTIONAL {
        ?ph a wm:PortfolioHealth ;
            wm:healthOfInvestor ?inv ;
            wm:riskScore ?riskScore .
      }
      OPTIONAL {
        ?hold a wm:PortfolioHolding ;
              wm:heldByInvestor ?inv ;
              wm:currentValue ?currVal .
      }
    }
    GROUP BY ?inv ?riskTolerance
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?holdingTotal) AS ?total_holding_value)
       (SUM(?sectorTotal) AS ?total_sector_allocation)
       (SUM(?cashTotal) AS ?total_cash_flow_amount)
WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?invId .

  OPTIONAL { ?inv wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?cv)) AS ?holdingTotal)
    WHERE {
      ?h a wm:PortfolioHolding ;
         wm:investorId ?invId ;
         wm:currentValue ?cv .
    }
    GROUP BY ?invId
  }

  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?ti)) AS ?sectorTotal)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?invId ;
          wm:totalInvestment ?ti .
    }
    GROUP BY ?invId
  }

  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?amt)) AS ?cashTotal)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?invId ;
          wm:amount ?amt .
    }
    GROUP BY ?invId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalHoldingValue ?totalGoalShortfall (?totalHoldingValue + ?totalGoalShortfall AS ?combinedMetric)
WHERE {
  # Investor basic info
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  # Portfolio health with riskScore filter
  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60)

  # Aggregate holdings per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?hv)) AS ?totalHoldingValue)
    WHERE {
      ?h a wm:PortfolioHolding ;
         wm:investorId ?investorId ;
         wm:currentValue ?hv .
    }
    GROUP BY ?investorId
  }

  # Aggregate goal shortfalls per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?totalGoalShortfall)
    WHERE {
      ?g a wm:InvestmentGoal ;
         wm:investorId ?investorId ;
         wm:shortfall ?sf .
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?combinedMetric) ?investorId
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_progress ?max_allocationPct ?diversificationScore WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?invGoal ;
            wm:progressPct ?progressPct .
      ?invGoal wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) < 25)
  }

  {
    SELECT ?investorId (MAX(xsd:decimal(?allocationPct)) AS ?max_allocationPct) WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:allocationOfInvestor ?invAlloc ;
            wm:allocationPct ?allocationPct .
      ?invAlloc wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (MAX(xsd:decimal(?allocationPct)) > 40)
  }

  {
    SELECT ?investorId (xsd:decimal(?divScore) AS ?diversificationScore) WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?invPH ;
          wm:diversificationScore ?divScore .
      ?invPH wm:investorId ?investorId .
      FILTER (xsd:decimal(?divScore) < 30)
    }
  }
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol ;
       wm:hasHolding ?hold ;
       wm:hasPortfolioHealth ?ph ;
       wm:hasRebalancingAction ?ra .

  FILTER(?riskTol = "Conservative") .

  ?hold rdf:type wm:PortfolioHolding ;
        wm:returnsPct ?returnsPct .
  FILTER(xsd:decimal(?returnsPct) < 0) .

  ?ph rdf:type wm:PortfolioHealth ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 70) .

  ?ra rdf:type wm:RebalancingAction ;
      wm:action ?action .
  FILTER(?action = "Tactical Increase") .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_shortfall ?total_cashflow ?de_risking_action_count
WHERE {
  {
    SELECT ?inv ?investorId ?investorName (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:investorId ?investorId .
      OPTIONAL { ?inv wm:investorName ?investorName . }
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?inv ?investorId ?investorName
  }
  {
    SELECT ?inv (SUM(xsd:decimal(?cfAmount)) AS ?total_cashflow)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (COUNT(?ra) AS ?de_risking_action_count)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:action ?raAction .
      FILTER(LCASE(STR(?raAction)) = "de-risking")
    }
    GROUP BY ?inv
  }
  FILTER(?total_shortfall > 0 && ?total_cashflow < 0)
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
