PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector
       (AVG(xsd:decimal(?allocationPct)) AS ?average_allocation_pct)
       (MAX(xsd:decimal(?allocationPct)) AS ?maximum_allocation_pct)
WHERE {
  ?alloc rdf:type wm:SectorAllocation ;
         wm:hasSector ?sectorNode ;
         wm:allocationPct ?allocationPct .
  OPTIONAL {
    ?sectorNode rdf:type wm:Sector ;
                rdfs:label ?sectorLabel .
  }
  BIND(COALESCE(?sectorLabel, "NULL") AS ?sector)
}
GROUP BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?goal_count WHERE {
  {
    SELECT ?investorId (COUNT(?goal) AS ?goal_count) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING ( ?goal_count >= 4 )
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:timeHorizon ?timeHorizon .
  FILTER(LCASE(STR(?timeHorizon)) = "long-term")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?ph .
  ?ph rdf:type wm:PortfolioHealth ;
      wm:liquidityScore ?liqScore ;
      wm:diversificationScore ?divScore .
  FILTER ( xsd:decimal(?liqScore) < 25 && xsd:decimal(?divScore) < 25 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?goalCount (COUNT(?investorId) AS ?investorCount)
WHERE {
  {
    SELECT ?investorId ?riskTolerance (COUNT(?goal) AS ?goalNum)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      OPTIONAL { ?inv wm:riskTolerance ?rt . }
      BIND(COALESCE(STR(?rt), "NULL") AS ?riskTolerance)
      ?inv wm:hasInvestmentGoal ?goal .
    }
    GROUP BY ?investorId ?riskTolerance
  }
  BIND(
    IF(?goalNum = 1, "1",
      IF(?goalNum = 2, "2",
        IF(?goalNum = 3, "3", "4+")
      )
    ) AS ?goalCount
  )
}
GROUP BY ?riskTolerance ?goalCount

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?rebalance_count WHERE {
  {
    SELECT ?investorId (COUNT(?sr) AS ?rebalance_count) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:triggeredAction ?action ;
          wm:scenarioRebalancingOfInvestor ?invSub .
      ?invSub wm:investorId ?investorId .
      FILTER(?action = "Automated Trigger")
    }
    GROUP BY ?investorId
    HAVING (COUNT(?sr) >= 1)
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?dividends)) AS ?totalDividends)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  ?holding a wm:PortfolioHolding ;
           wm:dividends ?dividends ;
           wm:heldByInvestor ?investor .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?totalDividends) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(DISTINCT ?investorId) AS ?distinct_investor_count)
WHERE {
  {
    SELECT ?investorId ?month
    WHERE {
      ?cf a wm:CashFlow ;
          wm:date ?date ;
          wm:investorId ?investorId .
      BIND(SUBSTR(STR(?date), 1, 7) AS ?month)
      FILTER(xsd:date(?date) >= "2025-01-01"^^xsd:date && xsd:date(?date) <= "2025-12-31"^^xsd:date)
    }
    GROUP BY ?investorId ?month
  }
}
GROUP BY ?month
ORDER BY ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress) (AVG(xsd:decimal(?riskScoreRaw)) AS ?riskScore)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:segment ?segment .
  FILTER(LCASE(STR(?segment)) = "moderate") .

  ?goal a wm:InvestmentGoal ;
        wm:progressPct ?progressPct ;
        wm:belongsToInvestor ?investor .

  ?ph a wm:PortfolioHealth ;
        wm:riskScore ?riskScoreRaw ;
        wm:healthOfInvestor ?investor .
}
GROUP BY ?investorId ?investorName
HAVING (AVG(xsd:decimal(?progressPct)) < 30 && AVG(xsd:decimal(?riskScoreRaw)) > 60)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER (xsd:decimal(?shortfall) > 0)
  }

  FILTER EXISTS {
    ?investor wm:hasSectorAllocation ?alloc .
    ?alloc wm:allocationPct ?allocPct .
    FILTER (xsd:decimal(?allocPct) > 35)
  }
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasScenarioRebalancing ?rebalance .
  ?rebalance wm:scenario ?scenario ;
            wm:hasMarketScenario ?market .
  FILTER(LCASE(STR(?scenario)) = "tactical") .
  ?market rdfs:label ?marketLabel .
  FILTER(LCASE(STR(?marketLabel)) = "bear market") .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(?invAvgShortfall) AS ?avg_goal_shortfall)
       (AVG(?invAvgDivScore) AS ?avg_diversification_score)
       (AVG(?invAvgRiskScore) AS ?avg_risk_score)
       (AVG(?invAvgLiqScore) AS ?avg_liquidity_score)
       (AVG(?invAvgGoalMatchPct) AS ?avg_goal_match_pct)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?invId .
  OPTIONAL { ?inv wm:riskTolerance ?riskTolRaw . }
  BIND(COALESCE(STR(?riskTolRaw), "NULL") AS ?risk_tolerance) .

  {
    SELECT ?invId (AVG(xsd:decimal(?shortfall)) AS ?invAvgShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?invId ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?invId
  }

  {
    SELECT ?invId
           (AVG(xsd:decimal(?divScore)) AS ?invAvgDivScore)
           (AVG(xsd:decimal(?riskScore)) AS ?invAvgRiskScore)
           (AVG(xsd:decimal(?liqScore)) AS ?invAvgLiqScore)
           (AVG(xsd:decimal(?goalMatchPct)) AS ?invAvgGoalMatchPct)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?invId ;
          wm:diversificationScore ?divScore ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liqScore ;
          wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?invId
  }
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (COALESCE(?holdingSum, 0) AS ?total_holding_value) (COALESCE(?allocSum, 0) AS ?total_sector_allocation_investment)
WHERE {
  ?sectorIRI a wm:Sector .
  OPTIONAL { ?sectorIRI rdfs:label ?sectorLabel . }
  BIND(COALESCE(?sectorLabel, "NULL") AS ?sector)

  OPTIONAL {
    SELECT ?sectorIRI (SUM(xsd:decimal(?cv)) AS ?holdingSum)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:hasSector ?sectorIRI ;
               wm:currentValue ?cv .
    }
    GROUP BY ?sectorIRI
  }

  OPTIONAL {
    SELECT ?sectorIRI (SUM(xsd:decimal(?ti)) AS ?allocSum)
    WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:hasSector ?sectorIRI ;
            wm:totalInvestment ?ti .
    }
    GROUP BY ?sectorIRI
  }
}
ORDER BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  FILTER EXISTS {
    ?cf a wm:CashFlow ;
        wm:cashFlowOfInvestor ?investor ;
        wm:date ?cfDate .
    FILTER(CONTAINS(LCASE(STR(?cfDate)), "2025"))
  }

  FILTER NOT EXISTS {
    ?ph a wm:PortfolioHolding ;
        wm:heldByInvestor ?investor ;
        wm:purchaseDate ?phDate .
    FILTER(CONTAINS(LCASE(STR(?phDate)), "2025"))
  }
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore ;
      wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?riskScore) > 70 && xsd:decimal(?divScore) < 30) .

  ?sa rdf:type wm:SectorAllocation ;
      wm:allocationOfInvestor ?investor ;
      wm:allocationPct ?allocPct .
  FILTER(xsd:decimal(?allocPct) > 40)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskScore
       (SUM(xsd:decimal(?holdingSum)) AS ?total_holding_value)
       (SUM(xsd:decimal(?sectorSum)) AS ?total_sector_allocation_investment)
WHERE {
  # Portfolio health per investor
  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId .
  OPTIONAL { ?ph wm:riskScore ?riskScoreRaw . }
  BIND(COALESCE(STR(?riskScoreRaw), "NULL") AS ?riskScore)

  # Aggregate holdings per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?cv)) AS ?holdingSum)
    WHERE {
      ?phold a wm:PortfolioHolding ;
             wm:investorId ?investorId ;
             wm:currentValue ?cv .
    }
    GROUP BY ?investorId
  }

  # Aggregate sector allocations per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?ti)) AS ?sectorSum)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:totalInvestment ?ti .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskScore

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?holding .
    ?holding wm:returnsPct ?returnsPct .
    FILTER(xsd:decimal(?returnsPct) < 0)
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 25)
  }

  FILTER EXISTS {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:diversificationScore ?divScore .
    FILTER(xsd:decimal(?divScore) < 40)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_progress ?riskScore ?withdrawal_total ?deposit_total ?sell_count
WHERE {
  # Base investor with portfolio health
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore .

  # Average progress of investment goals per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress)
    WHERE {
      ?invGoal a wm:Investor ;
               wm:investorId ?investorId ;
               wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  # Total withdrawal amount per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?withdrawal_total)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:type ?type ;
          wm:amount ?amount .
      FILTER(LCASE(STR(?type)) = "withdrawal")
    }
    GROUP BY ?investorId
  }

  # Total deposit amount per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?deposit_total)
    WHERE {
      ?cfDep a wm:CashFlow ;
             wm:investorId ?investorId ;
             wm:type ?type ;
             wm:amount ?amount .
      FILTER(LCASE(STR(?type)) = "deposit")
    }
    GROUP BY ?investorId
  }

  # Count of Sell rebalancing actions per investor
  {
    SELECT ?investorId (COUNT(?ra) AS ?sell_count)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:action ?action .
      FILTER(LCASE(STR(?action)) = "sell")
    }
    GROUP BY ?investorId
  }

  # Apply aggregated filters
  FILTER(?avg_progress < 30)
  FILTER(?riskScore > 60)
  FILTER(?withdrawal_total > ?deposit_total)
  FILTER(?sell_count > 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  # Cash‑flow aggregation with withdrawal > deposit
  {
    SELECT ?investor (SUM(?withdrawAmt) AS ?withdrawal_amount) (SUM(?depositAmt) AS ?deposit_amount)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:type ?cfType ;
          wm:amount ?cfAmount .
      BIND(xsd:decimal(?cfAmount) AS ?amtDec)
      BIND(IF(LCASE(?cfType) = "withdrawal", ?amtDec, 0) AS ?withdrawAmt)
      BIND(IF(LCASE(?cfType) = "deposit", ?amtDec, 0) AS ?depositAmt)
    }
    GROUP BY ?investor
    HAVING (SUM(?withdrawAmt) > SUM(?depositAmt))
  }

  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasSectorAllocation ?sectorAlloc ;
            wm:hasRebalancingAction ?rebAct ;
            wm:hasScenarioRebalancing ?scenReb .

  ?sectorAlloc wm:allocationPct ?allocPct .
  FILTER(xsd:decimal(?allocPct) > 20)

  ?rebAct wm:action ?rebAction .
  FILTER(LCASE(?rebAction) = "sell")

  ?scenReb wm:scenario ?scenario .
  FILTER(LCASE(?scenario) = "flash crash")
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:sectorFocus ?sectorFocus . }
  FILTER ( !BOUND(?sectorFocus) || STRLEN(STR(?sectorFocus)) = 0 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goal_context_value (COUNT(?goal) AS ?occurrences)
WHERE {
  ?investor a wm:Investor ;
            wm:riskTolerance ?riskTol ;
            wm:investorId ?invId ;
            wm:hasInvestmentGoal ?goal .
  FILTER(LCASE(STR(?riskTol)) = "aggressive")

  ?goal a wm:InvestmentGoal ;
        wm:investmentGoal ?goalLabel .

  ?cv a wm:ContextValue ;
      wm:contextValue ?cvLabel .

  FILTER(?goalLabel = ?cvLabel)
  BIND(?cvLabel AS ?goal_context_value)
}
GROUP BY ?goal_context_value

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:timeHorizon ?timeHorizon .
  FILTER(LCASE(STR(?timeHorizon)) = "long-term")

  ?goal a wm:InvestmentGoal ;
        wm:investmentGoal ?goalType ;
        wm:belongsToInvestor ?inv .
  FILTER(LCASE(STR(?goalType)) = "retirement planning")
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?sector (COUNT(?holdingId) AS ?holding_count)
WHERE {
  ?holding a wm:PortfolioHolding .
  ?holding wm:holdingId ?holdingId .

  OPTIONAL {
    ?holding wm:hasCategory ?cat .
    OPTIONAL { ?cat rdfs:label ?catLabel . }
  }
  BIND(COALESCE(STR(?catLabel), "NULL") AS ?category)

  OPTIONAL {
    ?holding wm:hasSector ?sec .
    OPTIONAL { ?sec rdfs:label ?secLabel . }
  }
  BIND(COALESCE(STR(?secLabel), "NULL") AS ?sector)
}
GROUP BY ?category ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:timeHorizon ?timeHorizon ;
            wm:hasSectorAllocation ?alloc .
  FILTER(LCASE(STR(?timeHorizon)) = "medium-term")

  ?alloc a wm:SectorAllocation ;
        wm:sector ?sector ;
        wm:allocationOfInvestor ?investor .
  FILTER(LCASE(STR(?sector)) = "technology")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (COUNT(?cashFlowId) AS ?cashFlowCount)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol ;
       wm:hasInvestmentGoal ?goal ;
       wm:hasCashFlow ?cashFlow .

  FILTER(LCASE(STR(?riskTol)) = "moderate") .

  ?goal wm:investmentGoal ?goalLabel .
  FILTER(LCASE(STR(?goalLabel)) = "income generation") .

  ?cashFlow wm:type ?cfType ;
            wm:cashFlowId ?cashFlowId .
  FILTER(LCASE(STR(?cfType)) = "dividend reinvestment") .
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?health_count ?holding_count
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER NOT EXISTS { ?inv wm:hasRiskTolerance ?rt . }

  {
    SELECT ?inv (COUNT(DISTINCT ?ph) AS ?health_count)
    WHERE {
      ?inv wm:hasPortfolioHealth ?ph .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (COUNT(DISTINCT ?ph2) AS ?holding_count)
    WHERE {
      ?inv wm:hasHolding ?ph2 .
    }
    GROUP BY ?inv
  }

  FILTER(?health_count > 0 && ?holding_count > 0)
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolLabel ?investmentTypeLabel (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolNode ;
            wm:hasHolding ?holding .
  ?riskTolNode a wm:RiskTolerance .
  OPTIONAL { ?riskTolNode rdfs:label ?riskTolLabelRaw . }
  BIND(COALESCE(?riskTolLabelRaw, STR(?riskTolNode)) AS ?riskTolLabel)

  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?it .
  ?it a wm:InvestmentType .
  OPTIONAL { ?it rdfs:label ?investmentTypeLabelRaw . }
  BIND(COALESCE(?investmentTypeLabelRaw, STR(?it)) AS ?investmentTypeLabel)
}
GROUP BY ?riskTolLabel ?investmentTypeLabel

