PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasCashFlow ?cashFlow .

  ?goal a wm:InvestmentGoal ;
        wm:investmentGoal ?goalLabel .
  FILTER(LCASE(STR(?goalLabel)) = "child education")

  ?cashFlow a wm:CashFlow ;
            wm:source ?source .
  FILTER(LCASE(STR(?source)) = "wallet")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasHolding ?holding ;
            wm:hasSectorAllocation ?allocation .

  ?holding a wm:PortfolioHolding ;
           wm:sector ?holdingSector .
  FILTER(LCASE(?holdingSector) = "real estate") .

  ?allocation a wm:SectorAllocation ;
              wm:sector ?allocationSector .
  FILTER(LCASE(?allocationSector) = "real estate") .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor_name
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investor_name ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "conservative") .
  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) < 35) .
  ?hold a wm:PortfolioHolding ;
        wm:investorId ?investorId ;
        wm:investmentName ?holdName .
  FILTER(LCASE(STR(?holdName)) = "gold") .
}
GROUP BY ?investorId ?investor_name

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasCashFlow ?cf ;
       wm:hasRebalancingAction ?ra .

  ?cf rdf:type wm:CashFlow ;
       wm:source ?cfSource .
  FILTER(LCASE(STR(?cfSource)) = "systematic") .

  ?ra rdf:type wm:RebalancingAction ;
       wm:logic ?raLogic .
  FILTER(LCASE(STR(?raLogic)) = "calendar-based") .
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel (AVG(xsd:decimal(?divScore)) AS ?avgDiversificationScore)
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:diversificationScore ?divScore ;
      wm:healthOfInvestor ?inv .
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?inv ;
           wm:hasSector ?sector .
  ?sector a wm:Sector .
  OPTIONAL { ?sector rdfs:label ?sectorLabelRaw . }
  BIND(COALESCE(?sectorLabelRaw, "NULL") AS ?sectorLabel)
}
GROUP BY ?sectorLabel
ORDER BY DESC(?avgDiversificationScore)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalContext (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:progressPct ?progressPct ;
        wm:investmentGoal ?goalContext .
  ?investor a wm:Investor ;
            wm:riskTolerance ?riskTolLiteral ;
            wm:hasRiskTolerance ?rt .
  ?rt a wm:RiskTolerance .
  FILTER(LCASE(STR(?riskTolLiteral)) = "aggressive")
}
GROUP BY ?goalContext
ORDER BY DESC(?avgProgress)
LIMIT 5
